from lib import *
S = SS('w104')
steps = [
    step("MQTT 的固定头 = 1 字节(高 4 位是报文类型,低 4 位是标志)+ 1~4 字节的“剩余长度”。手工连本机的迷你代理(MQTT 3.1.1)。CONNECT 25 字节:10 17 00 04 4d 51 54 54 04 02 00 3c 00 0b 77 31 30 34 2d 63 6c 69 65 6e 74 = 10(类型 1 = CONNECT)| 17(剩余长度 23)| 00 04 \"MQTT\"(协议名)| 04(协议级别 4 = 3.1.1)| 02(连接标志:Clean Session)| 00 3c(保活 60 秒)| 00 0b \"w104-client\"(客户端标识,11 字节)。CONNACK 4 字节:20 02 00 00 = 类型 2 | 剩余长度 2 | 会话存在标志 0 | 返回码 0(接受)。SUBSCRIBE 21 字节:82 13 00 01 00 0e \"sensors/+/temp\" 01 = 类型 8(标志必须是 0010)| 包标识 1 | 主题过滤器(+ 是单层通配符)| 请求的 QoS 1;SUBACK:90 03 00 01 01(类型 9,包标识 1,授予 QoS 1)。", t=tl(S(1)), mark=lidx(S(1), 'CONNECT(25 字节)', 'SUBSCRIBE(21 字节)'), done=lidx(S(1), 'CONNACK(4 字节)'), b=bars([['CONNECT', 25, '25 字节'], ['CONNACK', 4, '4 字节'], ['SUBSCRIBE', 21, '21 字节']], 25, mark=[0], done=[1, 2]), kv=KV([['CONNECT', '25 字节:10 17 + MQTT + 级别 4 + 保活 60'], ['CONNACK', '4 字节:20 02 00 00'], ['SUBSCRIBE', '21 字节,主题过滤器 sensors/+/temp']], ['CONNECT'])),
    step("PUBLISH 一条消息要多少字节?QoS 0:发布者发出 26 字节 30 18 00 12 \"sensors/room1/temp\" \"21.5\":30 = PUBLISH、QoS 0 | 18 = 剩余长度 24 | 00 12 + 18 字节主题 | 4 字节载荷。订阅者收到的也是同样的 26 字节。单条消息的固定开销只有 4 字节(固定头 2 + 主题长度字段 2),但主题名本身 18 字节每次都要带——MQTT 没有头部压缩。剩余长度是变长编码:载荷 100 字节 → 剩余长度 103,编码成 1 字节(67);载荷 127 字节 → 130,2 字节(82 01);128 字节 → 131,2 字节(83 01);16383 字节 → 16386,3 字节(82 80 01);16384 字节 → 16387,3 字节(83 80 01)。每字节的低 7 位是数据,最高位表示后面还有。", t=tl(S(2)), mark=lidx(S(2), '发布者发出', '订阅者收到'), done=lidx(S(2), '载荷   100', '载荷   127', '载荷   128', '载荷 16383', '载荷 16384'), b=bars([['固定头 + 主题长度字段', 4, '4 字节'], ['主题名', 18, '18 字节'], ['载荷', 4, '4 字节']], 18, mark=[1], done=[0, 2]), kv=KV([['QoS 0 PUBLISH', '26 字节 = 2 + 2 + 18 + 4'], ['剩余长度', '≤127 一字节,≤16383 两字节…'], ['主题名', '每次都带,无压缩']], ['QoS 0 PUBLISH'])),
    step("QoS 1(至少一次):PUBLISH 带包标识,接收方回 PUBACK;没收到就要用 DUP 标志重发。让代理故意不回第一次的 PUBACK:第一次 PUBLISH 是 32 13 00 08 \"q1/topic\" 00 07 \"payload\"(32 = PUBLISH、QoS 1、DUP 0,包标识 7),客户端 1 秒内没有收到 PUBACK。重发时头字节变成 3a(QoS 1 + DUP 1),包标识仍是 7,这次代理回 PUBACK 40 02 00 07。代理的记录:PUBLISH QoS1 pid=7(DUP 0),故意不回 PUBACK,PUBLISH QoS1 pid=7(DUP 1)——同一个包标识被收到了两次。所以 QoS 1 是“至少一次”,接收方可能看到重复。", t=tl(S(3)), mark=lidx(S(3), '第一次 PUBLISH', '重发 PUBLISH'), done=lidx(S(3), '代理看到的 QoS1'), kv=KV([['第一次 PUBLISH', '32 …(QoS 1,DUP 0,pid 7)'], ['重发', '3a …(DUP 1,pid 7)'], ['PUBACK', '40 02 00 07'], ['结果', '代理收到 pid 7 两次:至少一次']], ['结果'])),
    step("QoS 2(恰好一次):四步握手 PUBLISH → PUBREC → PUBREL → PUBCOMP。客户端 PUBLISH QoS 2(pid 9),代理回 PUBREC;此时订阅者还没有收到消息(代理在等 PUBREL);客户端发 PUBREL,代理回 PUBCOMP,PUBREL 之后订阅者才收到 “exactly once”。因为代理在 PUBREL 之前只是记下消息、PUBREL 之后才投递一次,所以即使 PUBLISH 被重发也不会重复。代价是 4 个包(2 个往返),是 QoS 0 的 4 倍的包数。", t=tl(S(4)), mark=lidx(S(4), 'C→S  PUBLISH QoS2', 'S→C  PUBREC', 'C→S  PUBREL', 'S→C  PUBCOMP'), done=lidx(S(4), '订阅者此时还没收到消息'), b=bars([['QoS 0 包数', 1, '1'], ['QoS 1 包数', 2, '2'], ['QoS 2 包数', 4, '4']], 4, mark=[2], done=[0, 1]), kv=KV([['握手', 'PUBLISH → PUBREC → PUBREL → PUBCOMP'], ['投递时机', '收到 PUBREL 之后才投递一次'], ['代价', '4 个包,2 个往返']], ['投递时机'])),
    step("保活与遗嘱。客户端声明保活 2 秒,之后不发任何包:代理在 3.11 秒(= 1.5 倍保活时间)后断开它,并发布它预先登记的遗嘱消息,订阅者在 3.1 秒后收到 “w104-dead went offline”(主题 clients/status)。对比:正常发 DISCONNECT(e0 00,2 字节)再关连接的客户端,订阅者没有收到遗嘱——遗嘱只在非正常断开时发布。保活靠 PINGREQ(c0 00)/ PINGRESP(d0 00):各 2 字节,在 0.1 ms 内一来一回,空闲时客户端每隔保活时间发一次,以证明自己还活着。", t=tl(S(5)), mark=lidx(S(5), '不发任何包、保活 2 秒', '正常 DISCONNECT'), done=lidx(S(5), 'PINGREQ'), b=bars([['保活时间', 2, '2 秒'], ['代理断开用时(1.5 倍)', 3.11, '3.11 秒']], 3.2, mark=[1], done=[0]), kv=KV([['保活 2 秒、不发包', '3.11 秒后被断开 + 发布遗嘱'], ['正常 DISCONNECT', 'e0 00,不发布遗嘱'], ['PINGREQ / PINGRESP', 'c0 00 / d0 00,各 2 字节']], ['保活 2 秒、不发包'])),
    step("保留消息。发布时带 RETAIN 标志(31 = PUBLISH + RETAIN 1)的 home/door = closed,代理存下最后一条。之后才来订阅的客户端,在 SUBACK 之后立刻收到这条消息(保留位 1,载荷 closed,订阅完成后 0.1 ms 内),不用等设备下一次发布。用途:设备的“最新状态”——比如门锁、开关。普通(非保留)消息发布的时候没有订阅者就丢了。", t=tl(S(6)), mark=lidx(S(6), '先发布 retain'), done=lidx(S(6), '先发布 retain'), kv=KV([['发布', '31 = PUBLISH + RETAIN'], ['晚到的订阅者', 'SUBACK 后立即收到最后一条'], ['用途', '设备最新状态']], ['晚到的订阅者'])),
]
A = mkartw('w104', 104, '网络协议,MQTT,物联网,QoS,保活,遗嘱,保留消息,真实验证,动画演示',
    '手工收发 MQTT 3.1.1 字节:CONNECT 25 字节、CONNACK 4 字节、PUBLISH 固定开销 4 字节加每次都带的主题名;剩余长度的变长编码;QoS 1 的重发会让代理收到同一个包标识两次;QoS 2 要 4 个包;保活 2 秒在 3.11 秒后触发遗嘱;保留消息让晚到的订阅者立刻拿到最新状态。',
    'MQTT 是物联网里最常用的发布 / 订阅协议:固定头只有两个字节,报文只有十几种,却有三档送达保证、保活、遗嘱和保留消息。这篇自己写了一个迷你的 MQTT 代理,手工发每个字节,把这些机制逐个做出来看。',
    [('26 字节', '一条 QoS 0、主题 sensors/room1/temp、载荷 21.5 的 PUBLISH 的总长度'), ('3.11 秒', '保活 2 秒的客户端不发任何包时,代理断开它并发布遗嘱所用的时间'), ('2 次', 'QoS 1 故意不回 PUBACK 后,代理收到同一个包标识的次数')],
    [('报文结构', '<p>固定头 1 字节类型加标志 + 变长的剩余长度;CONNECT 25 字节,CONNACK 4 字节。</p>'),
     ('PUBLISH 的开销', '<p>固定开销 4 字节,但每次都带完整主题名(无压缩);剩余长度用变长编码。</p>'),
     ('QoS 1', '<p>至少一次:PUBACK 丢了就用 DUP 重发,接收方可能看到重复。</p>'),
     ('QoS 2', '<p>恰好一次:四个包,PUBREL 之后才投递一次。</p>'),
     ('保活与遗嘱', '<p>超过 1.5 倍保活时间没有包,代理断开并发布遗嘱;正常 DISCONNECT 不发布。</p>'),
     ('保留消息', '<p>代理存下最后一条,晚到的订阅者立刻收到。</p>')],
    steps,
    [ENV_W + '。代理是我写的最小实现(只支持 CONNECT、SUBSCRIBE、PUBLISH QoS 0/1/2、PING、DISCONNECT、遗嘱、保留消息,不支持会话持久化、认证、TLS),全在本机;QoS 1 的“不回 PUBACK”是我故意设置的;没有使用任何公共 MQTT 代理',
     '没有验证:会话持久化(Clean Session = 0)与离线消息;MQTT 5.0 的新特性(原因码、共享订阅、主题别名);认证与 TLS(8883);QoS 订阅降级的全部规则;真实代理(Mosquitto、EMQX)的行为差异;大量订阅者时的扇出性能'],
    'MQTT')
